-- fishgame：fish 表加 icon 列（图鉴动态显示，/dex/table 下发图标三元组）。
-- 48 条既有条目回填 icon，逐字抄自客户端 fish_db.gd ENTRIES（shape/color/accent）。
-- icon JSON 形状 {"shape":"...","color":"#RRGGBB","accent":"#RRGGBB"}；新条目可留空（客户端回退默认图标）。
ALTER TABLE `fishgame_fish` ADD COLUMN `icon` text NOT NULL COMMENT '图标 JSON {shape,color,accent}，空=客户端默认' AFTER `flavor`;
